const r = $('Find Issues').first().json.report || {};
const pending = Array.isArray(r.pending_decision) ? r.pending_decision : [];
const unpaid = Array.isArray(r.approved_unpaid) ? r.approved_unpaid : [];
const disputed = Array.isArray(r.disputed_stale) ? r.disputed_stale : [];
const total = r.total_issues || 0;
const totalAmount = r.total_amount_pending || 0;

function esc(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function money(n) { return n != null && n > 0 ? Number(n).toLocaleString('es-ES', {minimumFractionDigits: 2}) + ' EUR' : '-'; }
function dateShort(s) { if (!s) return '-'; return new Date(s).toISOString().substring(0,10); }

const rowsPending = pending.map(i => `<tr style="background:${i.days_waiting > 14 ? '#fee' : '#fff8e0'}">
  <td>${esc(i.supplier_name || '?')}</td>
  <td>${esc(i.invoice_number || '-')}</td>
  <td>${esc(i.project_name)}</td>
  <td>${esc(i.category || '-')} / ${esc(i.trade_type || '-')}</td>
  <td>${dateShort(i.invoice_date)}</td>
  <td style="text-align:right;font-weight:600">${money(i.total_amount)}</td>
  <td style="text-align:right;font-weight:600">${i.days_waiting}d</td>
</tr>`).join('');

const rowsUnpaid = unpaid.map(i => `<tr>
  <td>${esc(i.supplier_name || '?')}</td>
  <td>${esc(i.invoice_number || '-')}</td>
  <td>${esc(i.project_name)}</td>
  <td>${dateShort(i.approved_at)}</td>
  <td style="text-align:right;font-weight:600">${money(i.total_amount)}</td>
  <td style="text-align:right;color:#c00;font-weight:600">${i.days_overdue}d</td>
</tr>`).join('');

const rowsDisputed = disputed.map(i => `<tr style="background:#fee">
  <td>${esc(i.supplier_name || '?')}</td>
  <td>${esc(i.invoice_number || '-')}</td>
  <td>${esc(i.project_name)}</td>
  <td>${dateShort(i.created_at)}</td>
  <td style="text-align:right;font-weight:600">${money(i.total_amount)}</td>
  <td style="text-align:right;font-weight:600">${i.days_disputed}d</td>
</tr>`).join('');

const sections = [];
if (pending.length > 0) {
  sections.push(`<h3 style="margin-top:24px">Pendientes de decision (${pending.length}, total ${money(totalAmount)})</h3><p style="font-size:13px;color:#555">Facturas subidas hace mas de 5 dias sin aprobar/rechazar. Decidir.</p>
<table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr style="background:#f0f0f3"><th align="left">supplier</th><th align="left">numero</th><th align="left">proyecto</th><th align="left">cat/gremio</th><th align="left">fecha</th><th align="right">importe</th><th align="right">esperando</th></tr></thead><tbody>${rowsPending}</tbody></table>`);
}
if (unpaid.length > 0) {
  sections.push(`<h3 style="margin-top:24px">Aprobadas sin pagar >30d (${unpaid.length})</h3><p style="font-size:13px;color:#555">Aprobaste estas facturas hace mas de 30 dias y siguen sin pagar. Marcar paid_at o renegociar plazo.</p>
<table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr style="background:#f0f0f3"><th align="left">supplier</th><th align="left">numero</th><th align="left">proyecto</th><th align="left">aprobada</th><th align="right">importe</th><th align="right">retraso</th></tr></thead><tbody>${rowsUnpaid}</tbody></table>`);
}
if (disputed.length > 0) {
  sections.push(`<h3 style="margin-top:24px">En disputa >14d (${disputed.length})</h3><p style="font-size:13px;color:#555">Facturas marcadas como disputed que llevan mas de 14 dias sin resolver. Cerrar conversacion.</p>
<table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr style="background:#f0f0f3"><th align="left">supplier</th><th align="left">numero</th><th align="left">proyecto</th><th align="left">creada</th><th align="right">importe</th><th align="right">dias</th></tr></thead><tbody>${rowsDisputed}</tbody></table>`);
}

const html = `<div style="font-family:system-ui,sans-serif;color:#222;max-width:780px">
<h2>Facturas - revision diaria (${total} pendientes)</h2>
${sections.join('\n')}
<p style="font-size:12px;color:#888;margin-top:24px">cron_invoice_approval_followup - generado ${new Date().toISOString()}</p>
</div>`;

const subject = `[Facturas] ${total} pendientes (${pending.length} sin decidir / ${unpaid.length} sin pagar >30d / ${disputed.length} en disputa)`;

return [{ json: { html, subject, total } }];
